diff --git a/index.js b/index.js
index 5ecd392..309e64b 100644
--- a/index.js
+++ b/index.js
@@ -81,8 +81,14 @@ export default function pLimit(concurrency) {
 					return;
 				}

-				const abortError = AbortSignal.abort().reason;
-
+				// A plain `Error` is used rather than `AbortSignal.abort().reason`, as a
+				// `DOMException` is not a native error and is therefore rejected by
+				// `instanceof`-style checks in assertion libraries and error serializers.
+				const abortError = new Error('The queue was cleared');
+				abortError.name = 'AbortError';
+
+				// Draining the queue rejects each pending promise exactly once and releases
+				// its entry. Already running functions are not in the queue, so they finish.
 				while (queue.size > 0) {
 					queue.dequeue().reject(abortError);
 				}
